WITH RECURSIVE PARAMS AS ( SELECT CASE WHEN TRIM(COALESCE(:VAR_DATA_INICIO, '')) REGEXP '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(:VAR_DATA_INICIO), '%d/%m/%Y') ELSE DATE(NULLIF(TRIM(COALESCE(:VAR_DATA_INICIO, '')), '')) END AS DT_INI_IN, CASE WHEN TRIM(COALESCE(:VAR_DATA_FIM, '')) REGEXP '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(:VAR_DATA_FIM), '%d/%m/%Y') ELSE DATE(NULLIF(TRIM(COALESCE(:VAR_DATA_FIM, '')), '')) END AS DT_FIM_IN ), P AS ( SELECT LEAST(DT_INI, DT_FIM) AS DT_INI, GREATEST(DT_INI, DT_FIM) AS DT_FIM, YEAR(GREATEST(DT_INI, DT_FIM)) AS ANO FROM ( SELECT COALESCE(DT_FIM_IN, CURDATE()) AS DT_FIM, COALESCE(DT_INI_IN, MAKEDATE(YEAR(COALESCE(DT_FIM_IN, CURDATE())), 1)) AS DT_INI FROM PARAMS ) X ), MESES AS ( SELECT 1 AS NUM_MES UNION ALL SELECT NUM_MES + 1 FROM MESES WHERE NUM_MES < 12 ), PERIODOS AS ( SELECT LPAD(m.NUM_MES, 2, '0') AS MES_NUM, CONCAT(LPAD(m.NUM_MES, 2, '0'), '/', p.ANO) AS PERIODO FROM MESES m CROSS JOIN P p WHERE LAST_DAY(MAKEDATE(p.ANO, 1) + INTERVAL (m.NUM_MES - 1) MONTH) >= p.DT_INI AND MAKEDATE(p.ANO, 1) + INTERVAL (m.NUM_MES - 1) MONTH <= p.DT_FIM ), VALORES AS ( SELECT per.PERIODO, d.ORDEM, d.HIERARQUIA, d.DESCRICAO, d.SINAL, d.RECUO, n.NOTA, SUM(COALESCE(t.BP_TECWAY, 0)) * 1000 AS VALOR FROM DET_DRE_TW d CROSS JOIN PERIODOS per LEFT JOIN CAD_CONTA_DRE_TW c ON c.ID_DET_DRE_TW = d.ID LEFT JOIN BP_TECWAY t ON TRIM(t.ID_CONTA_CONTABIL) = TRIM(c.ID_CONTA_CONTABIL) AND t.MES = per.PERIODO AND ( :VAR_EMPRESA IS NULL OR :VAR_EMPRESA = '' OR FIND_IN_SET(t.ID_EMPRESA, :VAR_EMPRESA) ) LEFT JOIN ( SELECT ID_DET_DRE_TW, MAX(NOTA) AS NOTA FROM DET_NOTAS WHERE MES = (SELECT DATE_FORMAT(DT_FIM, '%m/%Y') FROM P) AND ( :VAR_EMPRESA IS NULL OR :VAR_EMPRESA = '' OR FIND_IN_SET(EMPRESA, :VAR_EMPRESA) ) GROUP BY ID_DET_DRE_TW ) n ON n.ID_DET_DRE_TW = d.ID WHERE d.ID_ESTR_DRE_TW = 7 GROUP BY per.PERIODO, d.ORDEM, d.HIERARQUIA, d.DESCRICAO, d.SINAL, d.RECUO, n.NOTA ) SELECT ORDEM, HIERARQUIA, DESCRICAO, SINAL, NOTA, RECUO, MAX(CASE WHEN PERIODO LIKE '01/%' THEN VALOR END) AS VALOR_JAN, MAX(CASE WHEN PERIODO LIKE '02/%' THEN VALOR END) AS VALOR_FEV, MAX(CASE WHEN PERIODO LIKE '03/%' THEN VALOR END) AS VALOR_MAR, MAX(CASE WHEN PERIODO LIKE '04/%' THEN VALOR END) AS VALOR_ABR, MAX(CASE WHEN PERIODO LIKE '05/%' THEN VALOR END) AS VALOR_MAI, MAX(CASE WHEN PERIODO LIKE '06/%' THEN VALOR END) AS VALOR_JUN, MAX(CASE WHEN PERIODO LIKE '07/%' THEN VALOR END) AS VALOR_JUL, MAX(CASE WHEN PERIODO LIKE '08/%' THEN VALOR END) AS VALOR_AGO, MAX(CASE WHEN PERIODO LIKE '09/%' THEN VALOR END) AS VALOR_SET, MAX(CASE WHEN PERIODO LIKE '10/%' THEN VALOR END) AS VALOR_OUT, MAX(CASE WHEN PERIODO LIKE '11/%' THEN VALOR END) AS VALOR_NOV, MAX(CASE WHEN PERIODO LIKE '12/%' THEN VALOR END) AS VALOR_DEZ, (SELECT DT_INI FROM P) AS DATA_INICIO_USADA, (SELECT DT_FIM FROM P) AS DATA_FIM_USADA FROM VALORES GROUP BY ORDEM, HIERARQUIA, DESCRICAO, SINAL, NOTA, RECUO ORDER BY ORDEM;